#include "Aemeath/Infrastructure/Chat/OpenAICompatibleChatService.h"
#include "Aemeath/Infrastructure/Json/SimpleJson.h"
#include <stdexcept>
namespace J=Aemeath::Infrastructure::Json;namespace Aemeath::Infrastructure::Chat {
OpenAICompatibleChatService::OpenAICompatibleChatService(std::shared_ptr<Aemeath::Services::IHttpClient> h,std::string e,std::string k,std::string m):m_http(std::move(h)),m_endpoint(std::move(e)),m_apiKey(std::move(k)),m_model(std::move(m)){if(!m_http)throw std::invalid_argument("http client required");}
std::future<Aemeath::Core::Chat::ChatMessage> OpenAICompatibleChatService::SendAsync(std::vector<Aemeath::Core::Chat::ChatMessage> h,Aemeath::Core::Chat::ChatMessage u){return std::async(std::launch::async,[this,h=std::move(h),u=std::move(u)]() mutable {h.push_back(u);J::Value::Array a;for(auto&m:h){std::string r=m.role==Aemeath::Core::Chat::ChatRole::System?"system":m.role==Aemeath::Core::Chat::ChatRole::Assistant?"assistant":"user";a.emplace_back(J::Value::Object{{"role",r},{"content",m.content}});}auto body=J::Stringify(J::Value::Object{{"model",m_model},{"messages",a},{"stream",false}});Aemeath::Core::Network::HttpRequest q;q.method=Aemeath::Core::Network::HttpMethod::Post;q.url=m_endpoint;q.headers={{"Content-Type","application/json"},{"Accept","application/json"}};if(!m_apiKey.empty())q.headers["Authorization"]="Bearer "+m_apiKey;q.body.assign(body.begin(),body.end());auto r=m_http->SendAsync(std::move(q)).get();if(!r.IsSuccess())throw std::runtime_error("chat request failed: "+r.error);auto root=J::Parse(r.BodyText());auto*c=root.Find("choices");if(!c||!c->IsArray()||c->AsArray().empty())throw std::runtime_error("chat response has no choices");auto*m=c->AsArray()[0].Find("message");if(!m)throw std::runtime_error("chat response has no message");Aemeath::Core::Chat::ChatMessage x;x.id=J::String(root,"id");x.role=Aemeath::Core::Chat::ChatRole::Assistant;x.content=J::String(*m,"content");return x;});}}
